//! 🎯️ The actual selected Vec owner receives its original multi-item effect and records exact work.
use super::*;
use semio_framework_value_clone_source::RetainedCloneClose;
use std::mem::ManuallyDrop;
#[derive(Clone,Copy)]enum Op{Begin,Step}
struct Owner{value:ManuallyDrop<Option<Vec<u8>>>,close:ManuallyDrop<RetainedCloneClose>}
impl Owner{fn empty(&self)->bool{self.value.is_none()&&self.close.is_empty()}fn quote(&self,body:usize)->(RetirementDemand,u64){(self.close.next_owner_demands::<Vec<u8>>(self.value.is_some(),&None,body).unwrap(),self.close.next_owner_work::<Vec<u8>>(self.value.is_some(),&None,body).unwrap())}}
impl Drop for Owner{fn drop(&mut self){let empty=self.empty();assert!(empty||std::thread::panicking(),"selected owner remains resident");if empty{unsafe{ManuallyDrop::drop(&mut self.value);ManuallyDrop::drop(&mut self.close)}}}}
impl OriginalEffectProducer for Owner{
 type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=Op where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}
 fn source_turn<'a,'b>(&self,_:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{None}
 fn receive<'r,'a,'b>(&mut self,c:&mut Op,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>where 'b:'a{match c{Op::Begin=>{let turn=self.close.begin_granted(&mut*self.value,e);Ok(r.complete(turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into)))},Op::Step=>self.close.step_into(e,r)}}
 fn recover<'r,'a,'b>(&mut self,c:&mut Op,e:&mut RetainedAllocationEffect<'_>,r:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>where 'b:'a{match c{Op::Begin=>Err(ValueError::invariant("closed native birth cannot remain unrecorded")),Op::Step=>self.close.recover_step_into(e,r)}}
}
fn drive(owner:&mut OriginalEffectAuthority<Owner>,bank:&mut EffectBank,op:Op,g:RetainedCloneGrant,units:u64)->(RetainedCloneStep,u128,(usize,usize)){
 let(mut action,mut reply)=(None,None);let(mut spent,mut heap)=(0,(0usize,0usize));
 for _ in 0..128{let((poll,actual),observed)=observe_retirement_allocations(||bank.run(g,units,|effect|{let before=effect.performed_work();let ready=owner.drive(&mut op.clone(),effect,&mut action).unwrap();let work=effect.performed_work()-before;if ready{RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work})}else{RetainedWorkPoll::Pending{work}}}));spent+=poll.work();heap.0+=observed.0;heap.1+=observed.1;if let Some(actual)=actual{assert_eq!(actual,heap.0)}if matches!(poll,RetainedWorkPoll::Complete(_)){assert!(action.as_mut().unwrap().transfer_reply(&mut reply).unwrap());owner.finish(&mut action).unwrap();let step=reply.unwrap().unwrap();assert_eq!(bank.take_admitted(),if spent==0{None}else{Some(true)});bank.post(step.progress(),g,heap);return(step,spent,heap)}}
 panic!("same selected action stayed pending")
}
#[test]fn selected_retirement_keeps_the_actual_multi_item_loan_and_zero_item_denial(){
 let f:serde_json::Value=serde_json::from_str(include_str!("multi.json")).unwrap();let s=&f["stock"];let stock=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut bank=EffectBank::new(Wallet::new(stock,s["work"].as_u64().unwrap()));let mut owner=OriginalEffectAuthority::new(Owner{value:ManuallyDrop::new(Some(vec![73;f["count"].as_u64().unwrap()as usize])),close:ManuallyDrop::new(Default::default())});let items=f["items"].as_u64().unwrap()as usize;let body=items+std::mem::size_of::<usize>();assert_eq!(std::mem::size_of::<usize>(),f["lengthHeaderBytes"].as_u64().unwrap()as usize);
 for _ in 0..128{let(d,w)=owner.inspect(|p|p.quote(body));if owner.inspect(|p|p.value.is_none())&&d.copy_bytes==body&&d.capacity_bytes==0&&d.release_bytes==0{break}let g=RetainedCloneGrant{maximum_items:items,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let op=owner.inspect(|p|if p.value.is_some(){Op::Begin}else{Op::Step});drive(&mut owner,&mut bank,op,g,w);}
 let mut bulk=false;for _ in 0..128{let(d,w)=owner.inspect(|p|p.quote(body));let grant=RetainedCloneGrant{maximum_items:items,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};if d.copy_bytes==body&&d.capacity_bytes==0&&d.release_bytes==0{let(step,work,heap)=drive(&mut owner,&mut bank,Op::Step,RetainedCloneGrant{maximum_items:0,..grant},w);assert_eq!(step.progress(),Default::default());assert_eq!(work,0);assert_eq!(heap,(0,0));assert_eq!(owner.inspect(|p|p.quote(body)),(d,w));}let(step,work,heap)=drive(&mut owner,&mut bank,Op::Step,grant,w);if step.progress().copied_items==items{assert_eq!(step.progress().copied_bytes,body);assert_eq!(work,u128::from(f["work"].as_u64().unwrap()));assert_eq!(heap,(0,0));bulk=true;break}}assert!(bulk,"the selected native payload never received its actual multi-item grant");
 for _ in 0..128{if owner.inspect(Owner::empty){break}let(d,w)=owner.inspect(|p|p.quote(body));drive(&mut owner,&mut bank,Op::Step,RetainedCloneGrant{maximum_items:items,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth},w);}assert!(owner.inspect(Owner::empty));assert!(owner.into_producer().is_ok());
}
